#include <vector>
#include <unordered_map>

class Solution {
public:
    int countEquallySpacedValues(std::vector<int>& nums) {
        std::unordered_map<int, std::vector<int>> indices;
        for (int i = 0; i < (int)nums.size(); ++i) {
            indices[nums[i]].push_back(i);
        }

        int count = 0;
        for (auto const& [x, pos] : indices) {
            if (pos.size() <= 2) {
                count++;
            } else {
                int diff = pos[1] - pos[0];
                bool ok = true;
                for (size_t i = 2; i < pos.size(); ++i) {
                    if (pos[i] - pos[i - 1] != diff) {
                        ok = false;
                        break;
                    }
                }
                if (ok) count++;
            }
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int countEquallySpacedValues(int[] nums) {
        Map<Integer, List<Integer>> indices = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            indices.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }

        int count = 0;
        for (List<Integer> pos : indices.values()) {
            if (pos.size() <= 2) {
                count++;
            } else {
                int diff = pos.get(1) - pos.get(0);
                boolean ok = true;
                for (int i = 2; i < pos.size(); i++) {
                    if (pos.get(i) - pos.get(i - 1) != diff) {
                        ok = false;
                        break;
                    }
                }
                if (ok) count++;
            }
        }
        return count;
    }
}

